(() => {const select=document.getElementById('r5-study');if(!select)return;fetch('/assets/r5/comparisons.json').then(r=>{if(!r.ok)throw Error('Chart unavailable');return r.json()}).then(data=>{function draw(){const row=data[select.value],root=document.getElementById('r5-bars');root.replaceChildren();const max=Math.max(...row.values);row.labels.forEach((label,i)=>{const line=document.createElement('p'),name=document.createElement('strong'),bar=document.createElement('span');name.textContent=label+' · '+row.values[i]+' '+row.unit;bar.className='r5-bar';bar.style.width=(100*row.values[i]/max)+'%';line.append(name,bar);root.append(line)});document.getElementById('r5-note').textContent=row.note;document.getElementById('r5-source').href='/assets/r5/'+row.source+'.md'}select.addEventListener('change',draw);draw()}).catch(()=>{document.getElementById('r5-note').textContent='Chart could not load. Open the linked report for the complete measurements.'})})();
